head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL05505";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_attrReals();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05505.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "td_69", attr: "__html", fn: function () { return ([String(String(dma_irData.get("resoroomContn")).split(String((dma_pageContext.get("NEW_LINE") ?? ""))).join("<br/>"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(String(dma_irData.get("resoroomContn")).split(String((dma_pageContext.get("NEW_LINE") ?? ""))).join("<br/>"))) : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_picYn", fn: function(){ return ((dlt_irDataIrDataAttachVO.getCellData(0, "picYn") ?? (() => { throw new Error("unresolved:" + "attach.picYn"); })()) === 'Y'); } }, { id: "c_when_43", fn: function(){ return ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'HWP'); } }, { id: "c_when_47", fn: function(){ return ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'XLS'); } }, { id: "c_when_51", fn: function(){ return ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'DOC'); } }, { id: "c_when_55", fn: function(){ return ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PPT'); } }, { id: "c_when_59", fn: function(){ return ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PDF'); } }, { id: "c_otherwise_63", fn: function(){ return (!(((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'HWP') || ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'XLS') || ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'DOC') || ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PPT') || ((dlt_irDataIrDataAttachVO.getCellData(0, "fileSurFix") ?? (() => { throw new Error("unresolved:" + "attach.fileSurFix"); })()) === 'PDF'))); } }, { id: "if_picYn_2", fn: function(){ return ((dlt_irDataIrDataAttachVO.getCellData(0, "picYn") ?? (() => { throw new Error("unresolved:" + "attach.picYn"); })()) !== 'Y'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_31", entity: "dlt_irDataIrDataAttachVO", countIds: [], cells: [{ childId: "__rc3", fn: function (v, i) { return " " + String(v("attachFileNm")); } }] },
        { genId: "c_foreach_39", entity: "dlt_irDataIrDataAttachVO", countIds: [], cells: [{ childId: "__rc4", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc5", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc6", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc7", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc8", fn: function (v, i) { return " " + String(v("attachFileNm")); } }, { childId: "__rc9", fn: function (v, i) { return " " + String(v("attachFileNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Remove();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_FileDown_onclick
 * @description btn_FileDown 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_FileDown_onclick = async function(e){
    try {
        await scwin.fileDown('' + dlt_irDataIrDataAttachVO.getCellData(0, "reoroomId") + '','' + dlt_irDataIrDataAttachVO.getCellData(0, "attachSeq") + '','' + dlt_irDataIrDataAttachVO.getCellData(0, "attachFileChgDdtm") + '','' + dlt_irDataIrDataAttachVO.getCellData(0, "attachFileNm") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05505.btn_FileDown_onclick' }); }
};

/**
 * @method
 * @name btn_FileDown_2_onclick
 * @description btn_FileDown_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_FileDown_2_onclick = async function(e){
    try {
        await scwin.fileDown('' + dlt_irDataIrDataAttachVO.getCellData(0, "reoroomId") + '','' + dlt_irDataIrDataAttachVO.getCellData(0, "attachSeq") + '','' + dlt_irDataIrDataAttachVO.getCellData(0, "attachFileChgDdtm") + '','' + dlt_irDataIrDataAttachVO.getCellData(0, "attachFileNm") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05505.btn_FileDown_2_onclick' }); }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05505.btn_Search_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: action ?? "/list/irData.do",
        ref: "dma_SearchReq",
        target: "dlt_irDataIrDataAttachVO=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Modify
 * @description Modify 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Modify = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Modify",
        method: "post",
        action: action ?? "/list/irData.do",
        ref: "dma_ModifyReq",
        target: "dlt_irDataIrDataAttachVO=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Remove
 * @description Remove 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Remove = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Remove",
        method: "post",
        action: action ?? "/list/irData.do",
        ref: "dma_RemoveReq",
        target: "dlt_irDataIrDataAttachVO=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function (action) {
    try { return await $c.data.downFile(action ?? "/common/irDataFileDown.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    $c.util.getComponent('dma_SearchReq').set('method', 'searchIRData');
    const nr = await scwin.tx_fn_Search('/list/irData.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/ui/jsp/JLDFIL21210.xml", { "method": 'searchIRData' });
    }
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function () {
    $c.util.getComponent('dma_SearchReq').set('method', 'modifyIRDataForm');
    const nr = await scwin.tx_fn_Modify('/list/irData.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/ui/jsp/JLDFIL05506.xml", { "method": 'modifyIRDataForm' });
    }
};

/**
 * @method
 * @name remove
 * @description remove 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.remove = async function () {
    if (await $c.win.confirm("삭제하시겠습니까?")) {
        $c.util.getComponent('dma_SearchReq').set('method', 'removeIRData');
        await scwin.tx_fn_Remove('/list/irData.do');
    }
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {String} resoroomId resoroomId
 * @param {*} attachSeq attachSeq
 * @param {*} attachFileChgDdtm attachFileChgDdtm
 * @param {String} attachFileNm attachFileNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (resoroomId, attachSeq, attachFileChgDdtm, attachFileNm) {
    $c.util.getComponent('dma_SearchReq').set('resoroomId', resoroomId);
    $c.util.getComponent('dma_SearchReq').set('attachSeq', attachSeq);
    $c.util.getComponent('dma_SearchReq').set('attachFileChgDdtm', attachFileChgDdtm);
    $c.util.getComponent('dma_SearchReq').set('attachFileNm', attachFileNm);
    await scwin.tx_fn_FileDown('/common/irDataFileDown.do');
};
